import fs from 'fs/promises';
import path from 'path';

export interface TaskNode {
  id: string;
  name: string;
  node_type: 'DOMAIN' | 'TASK' | 'SUBTASK' | 'ATOMIC';
  parent_id: string | null;
  children_ids: string[];
  sources: string[];
  description?: string;
  verb?: string;
  domain?: string;
}

export interface DatasetStats {
  totalNodes: number;
  atomicActions: number;
  domains: number;
  verbs: number;
  avgDepth: number;
  maxDepth: number;
  nodesByType: Record<string, number>;
  nodesByDomain: Record<string, number>;
  topVerbs: Array<{ verb: string; count: number }>;
}

const DATA_DIR = path.join(process.cwd(), 'public', 'data');
const CACHE_FILE = path.join(DATA_DIR, 'dataset-cache.json');

// Cache for dataset operations
let cachedManifest: Record<string, TaskNode> | null = null;
let cachedStats: DatasetStats | null = null;

export async function loadManifest(): Promise<Record<string, TaskNode>> {
  if (cachedManifest) return cachedManifest;

  try {
    const manifestPath = path.join(DATA_DIR, 'manifest.json');
    const data = await fs.readFile(manifestPath, 'utf-8');
    cachedManifest = JSON.parse(data);
    return cachedManifest!;
  } catch (error) {
    console.warn('Manifest not found, returning empty dataset:', error);
    return {};
  }
}

export async function getDatasetStats(): Promise<DatasetStats> {
  if (cachedStats) return cachedStats;

  try {
    const statsPath = path.join(DATA_DIR, 'stats.json');
    const data = await fs.readFile(statsPath, 'utf-8');
    cachedStats = JSON.parse(data);
    return cachedStats!;
  } catch (error) {
    // Generate mock stats if file doesn't exist
    console.warn('Stats file not found, generating mock data');
    const mockStats: DatasetStats = {
      totalNodes: 1000000,
      atomicActions: 750000,
      domains: 35,
      verbs: 3479,
      avgDepth: 4.2,
      maxDepth: 8,
      nodesByType: {
        DOMAIN: 35,
        TASK: 50000,
        SUBTASK: 200000,
        ATOMIC: 750000,
      },
      nodesByDomain: {
        'work_healthcare': 120000,
        'work_manufacturing': 95000,
        'work_construction': 88000,
        'life_household': 150000,
        'life_personal_care': 75000,
      },
      topVerbs: [
        { verb: 'grasp', count: 45000 },
        { verb: 'move_to', count: 42000 },
        { verb: 'release', count: 38000 },
        { verb: 'inspect', count: 35000 },
        { verb: 'clean', count: 32000 },
      ],
    };
    cachedStats = mockStats;
    return mockStats;
  }
}

export async function searchTasks(query: string, limit: number = 50): Promise<TaskNode[]> {
  const manifest = await loadManifest();
  const lowerQuery = query.toLowerCase();

  const results = Object.values(manifest)
    .filter(node =>
      node.name.toLowerCase().includes(lowerQuery) ||
      node.id.toLowerCase().includes(lowerQuery) ||
      node.description?.toLowerCase().includes(lowerQuery)
    )
    .slice(0, limit);

  return results;
}

export async function getNodeById(id: string): Promise<TaskNode | null> {
  const manifest = await loadManifest();
  return manifest[id] || null;
}

export async function getNodesByDomain(domain: string): Promise<TaskNode[]> {
  const manifest = await loadManifest();
  return Object.values(manifest).filter(node => node.domain === domain);
}

export async function getNodesByType(type: string): Promise<TaskNode[]> {
  const manifest = await loadManifest();
  return Object.values(manifest).filter(node => node.node_type === type);
}

export async function getChildNodes(parentId: string): Promise<TaskNode[]> {
  const manifest = await loadManifest();
  const parent = manifest[parentId];

  if (!parent || !parent.children_ids) return [];

  return parent.children_ids
    .map(id => manifest[id])
    .filter(Boolean);
}

export async function getNodePath(nodeId: string): Promise<TaskNode[]> {
  const manifest = await loadManifest();
  const path: TaskNode[] = [];
  let currentNode = manifest[nodeId];

  while (currentNode) {
    path.unshift(currentNode);
    if (!currentNode.parent_id) break;
    currentNode = manifest[currentNode.parent_id];
  }

  return path;
}

export async function getDomains(): Promise<TaskNode[]> {
  const manifest = await loadManifest();
  return Object.values(manifest).filter(node => node.node_type === 'DOMAIN');
}

export async function getAtomicVerbs(): Promise<string[]> {
  const manifest = await loadManifest();
  const verbs = new Set<string>();

  Object.values(manifest).forEach(node => {
    if (node.node_type === 'ATOMIC' && node.verb) {
      verbs.add(node.verb);
    }
  });

  return Array.from(verbs).sort();
}

